// 1. Determine trigger mode and extract input payload
const isWebhook = Boolean($input.item.json.body || $input.item.json.headers);
const inputBody = isWebhook ? ($input.item.json.body || $input.item.json) : {};

// 2. Curated High-Intent Developer SEO Keyword Matrix for Suno API
const keywordMatrix = [
  {
    primaryKeyword: 'suno api key',
    secondaryKeywords: ['how to get suno api key', 'suno api authentication', 'suno api token'],
    category: 'Guides',
    topic: 'How to Get a Suno API Key and Authenticate Your First Music Generation Request',
    targetAudience: 'Developers looking for fast API key registration and authentication samples',
    targetSlug: 'how-to-get-suno-api-key'
  },
  {
    primaryKeyword: 'suno api prompt engineering',
    secondaryKeywords: ['suno ai prompt tags', 'suno style prompts', 'suno music genre prompts'],
    category: 'Tutorial',
    topic: 'Mastering Suno API Prompt Engineering: Metatags, Genre Stacking, and Dynamic Vocals',
    targetAudience: 'AI Audio engineers optimizing track consistency and style control',
    targetSlug: 'suno-api-prompt-engineering-guide'
  },
  {
    primaryKeyword: 'suno api python',
    secondaryKeywords: ['suno api python sdk', 'suno music generator python script', 'async music generation'],
    category: 'Engineering',
    topic: 'Building an Automated Music Bot with Suno API and Python in Under 50 Lines of Code',
    targetAudience: 'Python backend developers building automated music bots or audio services',
    targetSlug: 'build-ai-music-bot-python-suno-api'
  },
  {
    primaryKeyword: 'suno api stem separation',
    secondaryKeywords: ['suno vocal separation', 'extract instrumental suno api', 'stem track separation api'],
    category: 'Architecture',
    topic: 'AI Stem Separation with Suno API: Extracting Vocals and Instrumentals for Remixing',
    targetAudience: 'Audio SaaS developers building karaoke, remixing, or DAW integrations',
    targetSlug: 'suno-api-stem-separation-vocals-instrumentals'
  },
  {
    primaryKeyword: 'suno api webhook callbacks',
    secondaryKeywords: ['suno async task callback', 'suno webhook integration', 'polling vs webhook suno'],
    category: 'Engineering',
    topic: 'Production-Ready Webhook Architecture for Long-Running Suno API Audio Synthesis',
    targetAudience: 'Full-stack engineers building resilient background job workers for audio synthesis',
    targetSlug: 'suno-api-webhook-architecture-production-guide'
  },
  {
    primaryKeyword: 'suno api vs udio api',
    secondaryKeywords: ['suno vs udio developer comparison', 'best ai music api 2026', 'ai music api pricing'],
    category: 'Comparison',
    topic: 'Suno API vs Udio API: In-Depth Developer Comparison for Latency, Stems, and Pricing',
    targetAudience: 'CTOs and product managers choosing the best audio generation provider',
    targetSlug: 'suno-api-vs-udio-api-developer-comparison'
  }
];

// 3. Selection logic: Webhook override or schedule round-robin
let selectedTask;
if (inputBody.primaryKeyword || inputBody.topic) {
  selectedTask = {
    primaryKeyword: inputBody.primaryKeyword || 'suno api',
    secondaryKeywords: inputBody.secondaryKeywords || ['suno ai api', 'music generation api'],
    category: inputBody.category || 'Tutorial',
    topic: inputBody.topic || `Building with Suno API: ${inputBody.primaryKeyword}`,
    targetAudience: inputBody.targetAudience || 'Full-stack and AI audio developers',
    targetSlug: inputBody.targetSlug || (inputBody.primaryKeyword ? inputBody.primaryKeyword.toLowerCase().replace(/[^a-z0-9]+/g, '-') : 'suno-api-developer-guide')
  };
} else {
  // Deterministic rotation based on day of year
  const now = new Date();
  const startOfYear = new Date(now.getFullYear(), 0, 0);
  const diff = now - startOfYear;
  const dayOfYear = Math.floor(diff / (1000 * 60 * 60 * 24));
  const index = dayOfYear % keywordMatrix.length;
  selectedTask = keywordMatrix[index];
}

return {
  json: {
    triggerSource: isWebhook ? 'webhook' : 'schedule',
    timestamp: new Date().toISOString(),
    task: selectedTask
  }
};

// 1. Parse LLM response
const rawResponse = $input.item.json;
let parsedArticle;

try {
  const messageContent = rawResponse.choices[0].message.content;
  parsedArticle = typeof messageContent === 'string' ? JSON.parse(messageContent) : messageContent;
} catch (err) {
  throw new Error(`Failed to parse LLM JSON output: ${err.message}`);
}

const slug = (parsedArticle.slug || 'suno-api-guide').toLowerCase().replace(/[^a-z0-9]+/g, '-');
const canonicalUrl = `https://sunoapi.top/blog/${slug}`;
const publishedAt = new Date().toISOString();

// 2. Build Schema.org Structured Data (TechArticle + FAQPage + BreadcrumbList)
const techArticleSchema = {
  "@context": "https://schema.org",
  "@type": "TechArticle",
  "headline": parsedArticle.title,
  "description": parsedArticle.metaDescription,
  "url": canonicalUrl,
  "datePublished": publishedAt,
  "dateModified": publishedAt,
  "author": {
    "@type": "Organization",
    "name": "SunoAPI Team",
    "url": "https://sunoapi.top"
  },
  "publisher": {
    "@type": "Organization",
    "name": "SunoAPI",
    "url": "https://sunoapi.top",
    "logo": {
      "@type": "ImageObject",
      "url": "https://sunoapi.top/favicon.ico"
    }
  },
  "keywords": (parsedArticle.tags || []).join(', '),
  "inLanguage": "en-US",
  "isAccessibleForFree": true
};

const faqSchema = {
  "@context": "https://schema.org",
  "@type": "FAQPage",
  "mainEntity": (parsedArticle.faqs || []).map(faq => ({
    "@type": "Question",
    "name": faq.question,
    "acceptedAnswer": {
      "@type": "Answer",
      "text": faq.answer
    }
  }))
};

const breadcrumbSchema = {
  "@context": "https://schema.org",
  "@type": "BreadcrumbList",
  "itemListElement": [
    {
      "@type": "ListItem",
      "position": 1,
      "name": "Home",
      "item": "https://sunoapi.top"
    },
    {
      "@type": "ListItem",
      "position": 2,
      "name": "Blog",
      "item": "https://sunoapi.top/blog"
    },
    {
      "@type": "ListItem",
      "position": 3,
      "name": parsedArticle.title,
      "item": canonicalUrl
    }
  ]
};

// 3. Estimate Word Count and Validate E-E-A-T Quality Gate
const wordCount = (parsedArticle.contentMarkdown || '').split(/\s+/).filter(Boolean).length;

return {
  json: {
    title: parsedArticle.title,
    metaDescription: parsedArticle.metaDescription,
    slug,
    canonicalUrl,
    category: parsedArticle.category || 'Engineering',
    readTime: parsedArticle.readTime || '7 min read',
    excerpt: parsedArticle.excerpt,
    tags: parsedArticle.tags || ['suno api', 'ai music'],
    wordCount,
    contentMarkdown: parsedArticle.contentMarkdown,
    faqs: parsedArticle.faqs || [],
    schemas: {
      techArticle: techArticleSchema,
      faq: faqSchema,
      breadcrumb: breadcrumbSchema
    },
    publishedAt
  }
};

